<?php
session_start();require_once('dbstring.php');require_once('parent-utils.php');parent_portal_ensure_tables($con);
if(isset($_GET['logout'])){unset($_SESSION['PARENT_PORTAL_ID']);header('location:parent-portal.php');exit();}
if(parent_portal_current_parent($con)){header('location:parent-dashboard.php');exit();}
$message='';$tone='error';
if(isset($_POST['parent_login'])){
    if(!parent_portal_csrf_valid($_POST['csrf']??'')){$message='Your session expired. Please try again.';}else{$identity=trim((string)($_POST['identity']??''));$password=(string)($_POST['password']??'');$stmt=mysqli_prepare($con,"SELECT * FROM tblparentaccount WHERE email=? OR mobile=? LIMIT 1");mysqli_stmt_bind_param($stmt,'ss',$identity,$identity);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);$parent=$result?mysqli_fetch_assoc($result):null;mysqli_stmt_close($stmt);if($parent&&password_verify($password,$parent['passwordhash'])){if($parent['status']!=='active'){$message='This Parent Portal request is awaiting school approval.';}else{session_regenerate_id(true);$_SESSION['PARENT_PORTAL_ID']=$parent['parentid'];mysqli_query($con,"UPDATE tblparentaccount SET lastloginat=NOW() WHERE parentid='".mysqli_real_escape_string($con,$parent['parentid'])."'");header('location:parent-dashboard.php');exit();}}else{$message='The login details were not recognised.';}}
}
if(isset($_POST['parent_register'])){
    $name=trim((string)($_POST['fullname']??''));$email=strtolower(trim((string)($_POST['email']??'')));$mobile=trim((string)($_POST['mobile']??''));$student=trim((string)($_POST['studentid']??''));$guardian=trim((string)($_POST['guardiancontact']??''));$relationship=trim((string)($_POST['relationship']??''));$password=(string)($_POST['password']??'');
    if(!parent_portal_csrf_valid($_POST['csrf']??'')){$message='Your session expired. Please try again.';}elseif($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$mobile===''||$student===''||$guardian===''||strlen($password)<8){$message='Complete all fields and use a password of at least 8 characters.';}else{$stmt=mysqli_prepare($con,"SELECT userid,nextofkin_contact FROM tblsystemuser WHERE userid=? AND systemtype='Student' LIMIT 1");mysqli_stmt_bind_param($stmt,'s',$student);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);$studentRow=$result?mysqli_fetch_assoc($result):null;mysqli_stmt_close($stmt);if(!$studentRow||!parent_portal_phone_matches($guardian,$studentRow['nextofkin_contact'])){$message='The student ID and guardian contact do not match the school record.';}else{$id=parent_portal_id();$hash=password_hash($password,PASSWORD_DEFAULT);$status='pending';$stmt=mysqli_prepare($con,'INSERT INTO tblparentaccount(parentid,fullname,mobile,email,passwordhash,status) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($stmt,'ssssss',$id,$name,$mobile,$email,$hash,$status);if($stmt&&mysqli_stmt_execute($stmt)){$link=mysqli_prepare($con,'INSERT INTO tblparentstudentlink(parentid,studentid,relationshiptext,status) VALUES(?,?,?,"pending")');mysqli_stmt_bind_param($link,'sss',$id,$student,$relationship);mysqli_stmt_execute($link);mysqli_stmt_close($link);$message='Your request was sent to the school for approval. You will be able to sign in once the link is verified.';$tone='success';}else{$message='An account already exists with this email address, or the request could not be saved.';}if($stmt)mysqli_stmt_close($stmt);}}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Parent Portal | Awuah Preparatory School</title><style>:root{--navy:#163656;--green:#08766f;--paper:#f3f7fa;--line:#d7e2ea}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:#1d3042;font:15px Arial,sans-serif}.wrap{max-width:980px;margin:auto;padding:38px 18px}.hero{padding:35px;border-radius:20px;background:linear-gradient(120deg,var(--navy),var(--green));color:#fff}.hero h1{margin:7px 0;font:600 36px Georgia,serif}.hero p{max-width:630px;color:#ddecf0;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:24px}.card h2{margin:0 0 8px;font:600 24px Georgia,serif;color:var(--navy)}label{display:block;margin:12px 0 5px;font-weight:bold;font-size:13px}input,select{width:100%;padding:11px;border:1px solid #c9d7e1;border-radius:8px;font:inherit}button{margin-top:18px;border:0;border-radius:8px;background:var(--green);color:#fff;padding:12px 15px;font-weight:bold;cursor:pointer}.message{margin:20px 0 0;padding:13px;border-radius:8px}.error{background:#fff0f0;color:#9f2933}.success{background:#e6f7ef;color:#126443}.note{color:#617588;line-height:1.55;font-size:13px}.back{color:#fff}@media(max-width:700px){.grid{grid-template-columns:1fr}.wrap{padding:20px 12px}.hero{padding:25px}.hero h1{font-size:29px}}</style></head><body><main class="wrap"><section class="hero"><a class="back" href="website.php">← School website</a><h1>Parent Portal</h1><p>A secure space for Awuah Preparatory School parents and guardians. Accounts are approved by the school before children’s information becomes available.</p></section><?php if($message!==''){?><p class="message <?php echo parent_portal_safe($tone);?>"><?php echo parent_portal_safe($message);?></p><?php }?><div class="grid"><section class="card"><h2>Sign in</h2><p class="note">Use the email address or mobile number registered for your Parent Portal account.</p><form method="post"><input type="hidden" name="csrf" value="<?php echo parent_portal_safe(parent_portal_csrf());?>"><label>Email or mobile<input name="identity" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button name="parent_login">Sign in securely</button></form></section><section class="card"><h2>Request access</h2><p class="note">We verify the guardian contact against the child’s school record and then an administrator approves the connection.</p><form method="post"><input type="hidden" name="csrf" value="<?php echo parent_portal_safe(parent_portal_csrf());?>"><label>Full name<input name="fullname" required></label><label>Email address<input name="email" type="email" required></label><label>Mobile number<input name="mobile" required></label><label>Child’s student ID<input name="studentid" required></label><label>Guardian contact on school record<input name="guardiancontact" required></label><label>Relationship<select name="relationship"><option>Parent</option><option>Mother</option><option>Father</option><option>Guardian</option></select></label><label>Create password<input name="password" type="password" minlength="8" required></label><button name="parent_register">Send access request</button></form></section></div></main></body></html>
